  TestValidator.predicate(
    "deleted department not visible in list",
    () => !page.data.some((d) => d.id === createdDepartment.id),
  );
  TestValidator.predicate(
    "all returned departments are not marked deleted",
    () => page.data.every((d) => d.deleted_at === null),
  );
}

