    tags.Type<"int32"> &
    tags.Minimum<1> &
    tags.Maximum<100>;
  const created: IErpHrmTimeTrackingProject.ISummary[] = [];
  const statusSet = ["active", "archived"] as const;
  for (const status of statusSet) {
