    await api.functional.erpHrmTimeTracking.member.projects.create(
      memberConnection,
      {
        body: {
          name: RandomGenerator.name(),
          color: "#1A73E8",
          status: "archived",
        } satisfies IErpHrmTimeTrackingProject.ICreate,
      },
    );
