      },
    );
  typia.assert(afterTitleUpdate);
  TestValidator.equals(
    "title unchanged after rejected assignment",
    afterTitleUpdate.title,
    updatedTitle,
  );
  TestValidator.equals(
    "assignee remains null after rejected assignment",
    afterTitleUpdate.assignedEmployee,
    null,
  );
}

