  typia.assert(timelogTaskB1);
  const timelogNoTask =
    await generate_random_erp_hrm_time_tracking_member_timelogs_create(
      memberConnection,
      {
        body: {
          ...typia.random<IErpHrmTimeTrackingTimelog.ICreate>(),
          work_date: workDateEnd.toISOString(),
          start_time: null,
