    await generate_random_erp_hrm_time_tracking_member_projects_create(
      memberConnection,
      {
        body: {
          ...typia.random<IErpHrmTimeTrackingProject.ICreate>(),
          name: `${RandomGenerator.name(2)}-${RandomGenerator.alphabets(6)}`,
          color: "#22c55e",
