          definitionFilters: [
            {
              field_key: "project",
              operator: "eq",
              value_text: "all",
              value_text_2: null,
              is_enabled: true,
              display_order: 1,
            },
          ] satisfies IErpHrmTimeTrackingReportDefinitionFilter.ICreate[],
        } satisfies IErpHrmTimeTrackingReportDefinition.ICreate,
      },
    );
