          snapshot_action_summary_keyword: keyword,
          from: from.toISOString(),
          to: to.toISOString(),
          page: current,
          limit: limit,
          sort: "created_at",
          sortOrder: "asc",
        } satisfies IErpHrmTimeTrackingActivityLogEntrySnapshot.IRequest,
