  TestValidator.equals(
    "status remains submitted",
    afterRejectTimesheet.status,
    submittedTimesheet.status,
  );
  TestValidator.equals(
    "rejectedAt remains null",
    afterRejectTimesheet.rejectedAt,
    null,
  );
}

